#!/usr/bin/env python3
"""SPQR Jeopardy - single-file public multiplayer server.
No third-party packages, WebSockets, requirements.txt, or separate index.html required.
"""
import json
import os
import socket
import threading
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlparse, parse_qs

HOST = "0.0.0.0"
PORT = int(os.environ.get("PORT", "8000"))
LOCK = threading.RLock()
PALETTE = ['#e04f5f','#4fa3e0','#e0b04f','#6fbf7f','#b06fe0','#e0824f','#4fd6c8','#e04fd0']
CURSOR_TTL = 5.0
PLAYER_TTL = 12.0
REVEAL_DURATION = 2.5
INDEX_HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<title>SPQR Jeopardy</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Cinzel:wght@500;700;900&family=EB+Garamond:ital,wght@0,400;0,600;1,400&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --maroon-900:#2a0a0f; --maroon-800:#3d0f16; --maroon-700:#54141d;\n    --gold:#d4af37; --gold-light:#f3d878; --gold-dim:#8a7127;\n    --marble-1:#ece6d8; --marble-2:#d9d0ba; --green:#3f7a4e; --red:#8c2b2b;\n  }\n  *{box-sizing:border-box; cursor:none;}\n  html,body{margin:0;padding:0;height:100%;}\n  body{\n    font-family:'EB Garamond', serif;\n    background:\n      radial-gradient(circle at 20% 10%, rgba(212,175,55,0.08), transparent 40%),\n      radial-gradient(circle at 80% 90%, rgba(212,175,55,0.06), transparent 45%),\n      repeating-linear-gradient(135deg, rgba(255,255,255,0.02) 0 2px, transparent 2px 6px),\n      linear-gradient(160deg, var(--maroon-900), var(--maroon-800) 55%, #1c0609);\n    color:var(--marble-1); min-height:100vh; overflow-x:hidden;\n  }\n  .app{max-width:1150px;margin:0 auto;padding:22px 18px 60px;position:relative;}\n  .titlebar{text-align:center;margin-bottom:18px;}\n  .titlebar h1{\n    font-family:'Cinzel',serif; font-weight:900; font-size:clamp(28px,5vw,46px);\n    letter-spacing:4px; margin:0; color:var(--gold-light);\n    text-shadow:0 2px 0 #000, 0 0 18px rgba(212,175,55,0.35);\n  }\n  .titlebar .sub{ font-family:'Cinzel',serif; letter-spacing:2px; font-size:12px; color:var(--gold-dim); text-transform:uppercase; margin-top:4px; }\n  .laurels{font-size:20px;opacity:.85;letter-spacing:6px;}\n\n  .warning-banner{\n    max-width:440px; margin:0 auto 16px; background:rgba(140,43,43,0.25); border:1px solid #c95a5a;\n    color:#f3d0d0; font-size:13px; line-height:1.5; padding:12px 16px; border-radius:10px; text-align:center;\n  }\n  .warning-banner b{color:#ffdede;}\n\n  .panel{\n    max-width:440px;margin:0 auto 50px; text-align:center;\n    background:linear-gradient(160deg,var(--maroon-700),var(--maroon-800));\n    border:1px solid var(--gold-dim); border-radius:14px; padding:32px 28px;\n    box-shadow:0 20px 50px rgba(0,0,0,.5), inset 0 0 40px rgba(212,175,55,0.06);\n  }\n  .panel p{color:var(--marble-2); font-size:16px; margin-top:0;}\n  .panel input{\n    width:100%; padding:12px 14px; font-size:17px; border-radius:8px;\n    border:1px solid var(--gold-dim); background:#1e0a0d; color:var(--marble-1);\n    font-family:'EB Garamond',serif; margin-bottom:14px;\n  }\n  .panel input:focus{outline:2px solid var(--gold);}\n  .lobby-status-pill{\n    display:inline-block; font-family:'Cinzel',serif; font-size:12px; color:var(--gold-light);\n    background:rgba(0,0,0,0.3); border:1px solid rgba(212,175,55,0.35); border-radius:20px;\n    padding:5px 14px; margin-bottom:16px; letter-spacing:.5px;\n  }\n  button{ font-family:'Cinzel',serif; border:none; letter-spacing:1px; }\n  .btn-gold{\n    background:linear-gradient(180deg,var(--gold-light),var(--gold) 60%,var(--gold-dim));\n    color:#2a1c04; font-weight:700; padding:12px 20px; border-radius:8px;\n    box-shadow:0 4px 0 #6d5a1c, 0 6px 14px rgba(0,0,0,.4); transition:transform .05s ease, filter .1s ease;\n  }\n  .btn-gold:hover{filter:brightness(1.06);}\n  .btn-gold:active{transform:translateY(3px); box-shadow:0 1px 0 #6d5a1c;}\n  .btn-gold:disabled{opacity:.5; filter:none;}\n  .btn-ghost{ background:transparent; border:1px solid var(--gold-dim); color:var(--gold-light); padding:8px 14px; border-radius:7px; font-size:13px; }\n  .btn-ghost:hover{background:rgba(212,175,55,0.1);}\n\n  .lobby-title{font-family:'Cinzel',serif; color:var(--gold-light); font-size:20px; margin-bottom:6px; letter-spacing:1px;}\n  .lobby-sub{color:var(--marble-2); font-size:14px; margin-bottom:18px;}\n  .lobby-list{list-style:none; padding:0; margin:0 0 22px; text-align:left; min-height:8px;}\n  .lobby-list li{\n    display:flex; align-items:center; gap:10px; padding:9px 12px; margin-bottom:7px;\n    background:rgba(0,0,0,0.25); border-radius:8px; border:1px solid rgba(212,175,55,0.2);\n    font-size:15px; animation:pop-in .25s ease;\n  }\n  @keyframes pop-in{ from{opacity:0; transform:translateY(-4px);} to{opacity:1; transform:translateY(0);} }\n  .lobby-list .dot{width:11px;height:11px;border-radius:50%;flex-shrink:0; box-shadow:0 0 6px rgba(0,0,0,.5);}\n  .lobby-list .you-tag{margin-left:auto; font-size:11px; color:var(--gold-dim); font-family:'Cinzel',serif;}\n  .lobby-empty{color:var(--gold-dim); font-size:13px; padding:10px 0;}\n  .status-line{font-size:12px; color:var(--gold-dim); margin-top:10px; min-height:16px;}\n  .share-hint{\n    font-size:12.5px; color:var(--marble-2); background:rgba(0,0,0,0.25);\n    border:1px dashed rgba(212,175,55,0.35); border-radius:8px; padding:10px 12px; margin-bottom:18px;\n  }\n\n  .scoreboard{ display:flex; flex-wrap:wrap; gap:10px; justify-content:center; margin-bottom:22px; }\n  .chip{\n    display:flex; align-items:center; gap:8px; background:rgba(0,0,0,0.25);\n    border:1px solid rgba(212,175,55,0.35); border-radius:30px; padding:7px 14px 7px 8px; font-size:14px;\n  }\n  .dot{width:12px;height:12px;border-radius:50%; box-shadow:0 0 6px rgba(0,0,0,.5);}\n  .chip .score{font-weight:700; color:var(--gold-light); font-family:'Cinzel',serif; margin-left:2px;}\n  .chip .you{font-size:10px; color:var(--gold-dim); margin-left:2px;}\n  .toolbar{display:flex; justify-content:center; gap:10px; margin-bottom:14px;}\n\n  .board{\n    display:grid; grid-template-columns:repeat(5,1fr); gap:6px;\n    background:rgba(0,0,0,0.25); padding:8px; border-radius:12px; border:1px solid rgba(212,175,55,0.3);\n  }\n  .cat-cell{\n    font-family:'Cinzel',serif; background:linear-gradient(180deg,var(--maroon-700),var(--maroon-900));\n    color:var(--gold-light); text-align:center; padding:14px 6px; border-radius:8px;\n    font-size:clamp(11px,1.6vw,14px); font-weight:700; letter-spacing:.5px; min-height:56px;\n    display:flex; align-items:center; justify-content:center; border:1px solid rgba(212,175,55,0.25);\n    text-shadow:0 1px 0 #000;\n  }\n  .clue-cell{\n    background:\n      linear-gradient(180deg, rgba(255,255,255,0.03), transparent),\n      radial-gradient(circle at 30% 20%, rgba(212,175,55,0.12), transparent 60%),\n      linear-gradient(160deg,#5c1b23,#3d0f16);\n    border:1px solid rgba(212,175,55,0.35); border-radius:8px;\n    display:flex; align-items:center; justify-content:center;\n    font-family:'Cinzel',serif; font-size:clamp(18px,3vw,26px); font-weight:700; color:var(--gold-light);\n    min-height:64px; transition:transform .12s ease, box-shadow .12s ease; text-shadow:0 2px 3px #000;\n  }\n  .clue-cell:not(.used):hover{transform:translateY(-2px); box-shadow:0 8px 16px rgba(0,0,0,.4);}\n  .clue-cell.used{ background:rgba(0,0,0,0.35); color:rgba(212,175,55,0.25); transform:none; box-shadow:none; }\n\n  .overlay{\n    position:fixed; inset:0; background:rgba(10,2,4,0.82);\n    display:flex; align-items:center; justify-content:center; z-index:50; padding:20px;\n  }\n  .clue-card{\n    width:min(720px,94vw); background:linear-gradient(160deg,var(--maroon-700),var(--maroon-900));\n    border:1px solid var(--gold-dim); border-radius:16px; padding:34px 30px; text-align:center;\n    box-shadow:0 30px 70px rgba(0,0,0,.6), inset 0 0 60px rgba(212,175,55,0.05);\n  }\n  .clue-card .cat-label{ font-family:'Cinzel',serif; letter-spacing:2px; text-transform:uppercase; color:var(--gold-dim); font-size:13px; margin-bottom:6px; }\n  .clue-card .value-label{ font-family:'Cinzel',serif; color:var(--gold-light); font-size:22px; font-weight:900; margin-bottom:18px; }\n  .clue-text{ font-size:clamp(19px,2.6vw,26px); line-height:1.5; margin:10px 0 24px; color:var(--marble-1); }\n  .answer-text{\n    font-family:'Cinzel',serif; color:#bfe3c8; font-size:18px; margin-bottom:18px;\n    padding:10px 14px; border:1px dashed rgba(191,227,200,0.4); border-radius:8px; display:inline-block;\n  }\n  .buzz-status{ font-family:'Cinzel',serif; color:var(--gold-light); margin-bottom:16px; font-size:15px; min-height:22px; }\n  .clue-actions{display:flex; gap:12px; justify-content:center; flex-wrap:wrap;}\n  .btn-correct{background:linear-gradient(180deg,#6fbf7f,var(--green)); color:#0d2412; padding:11px 20px; border-radius:8px; font-weight:700; box-shadow:0 4px 0 #285a34;}\n  .btn-wrong{background:linear-gradient(180deg,#c95a5a,var(--red)); color:#320b0b; padding:11px 20px; border-radius:8px; font-weight:700; box-shadow:0 4px 0 #5a1717;}\n  .btn-buzz{ font-size:20px; padding:16px 46px; border-radius:50px; }\n\n  #cursor-layer{position:fixed; inset:0; pointer-events:none; z-index:500;}\n  .cursor{position:absolute; top:0; left:0; will-change:transform; display:flex; flex-direction:column; align-items:flex-start;}\n  .cursor svg{filter:drop-shadow(0 2px 3px rgba(0,0,0,.6));}\n  .cursor .label{\n    margin-top:1px; margin-left:15px; background:rgba(0,0,0,0.55); padding:2px 8px; border-radius:10px;\n    font-size:11px; font-family:'Cinzel',serif; color:#fff; white-space:nowrap; border:1px solid rgba(255,255,255,0.15);\n  }\n\n  .hidden{display:none !important;}\n  .footer-note{ text-align:center; color:var(--gold-dim); font-size:12px; margin-top:22px; letter-spacing:.5px; }\n</style>\n</head>\n<body>\n\n<div id=\"cursor-layer\"></div>\n\n<div class=\"app\">\n  <div class=\"titlebar\">\n    <div class=\"laurels\">🏛️ ⚜️ 🏛️</div>\n    <h1>SPQR JEOPARDY</h1>\n    <div class=\"sub\">Ancient Rome Trivia — Play Live With Friends</div>\n  </div>\n\n  <div id=\"server-warning\" class=\"warning-banner hidden\">\n    ⚠️ <b>Can't reach the game server.</b> Make sure <code>server.py</code> is still running in your terminal, then reload this page.\n  </div>\n\n  <div id=\"start-screen\" class=\"panel\">\n    <div id=\"lobby-status-pill\" class=\"lobby-status-pill hidden\"></div>\n    <p id=\"start-copy\">Enter your name to create or join the lobby on this server.</p>\n    <input id=\"name-input\" maxlength=\"18\" placeholder=\"Your name, citizen...\" />\n    <button class=\"btn-gold\" id=\"connection-test-btn\" type=\"button\" style=\"width:100%;margin-bottom:8px;\">Test Server Connection</button>\n    <button class=\"btn-gold\" id=\"join-btn\" style=\"width:100%;\">Enter the Forum</button>\n    <div class=\"status-line\" id=\"join-status\"></div>\n  </div>\n\n  <div id=\"lobby-screen\" class=\"panel hidden\">\n    <div class=\"lobby-title\">⚔️ The Forum — Lobby</div>\n    <div class=\"lobby-sub\" id=\"lobby-sub\">Waiting for everyone to gather.</div>\n    <div class=\"share-hint\">📜 Friends on your Wi-Fi can join at the network address printed in your terminal when the server started.</div>\n    <ul class=\"lobby-list\" id=\"lobby-list\"></ul>\n    <button class=\"btn-gold\" id=\"start-game-btn\" style=\"width:100%;\">Start Game</button>\n    <div class=\"status-line\">Anyone in the lobby can start once everyone's in.</div>\n  </div>\n\n  <div id=\"game-screen\" class=\"hidden\">\n    <div class=\"scoreboard\" id=\"scoreboard\"></div>\n    <div class=\"toolbar\">\n      <button class=\"btn-ghost\" id=\"reset-btn\">⟲ New Game (back to lobby, reset scores)</button>\n    </div>\n    <div class=\"board\" id=\"board\"></div>\n    <div class=\"footer-note\">Click a value to open a clue · First to buzz answers out loud · Anyone can mark Correct / Wrong</div>\n  </div>\n</div>\n\n<div id=\"clue-overlay\" class=\"overlay hidden\">\n  <div class=\"clue-card\">\n    <div class=\"cat-label\" id=\"clue-cat\"></div>\n    <div class=\"value-label\" id=\"clue-value\"></div>\n    <div class=\"clue-text\" id=\"clue-text\"></div>\n    <div id=\"answer-block\" class=\"hidden\"><div class=\"answer-text\" id=\"answer-text\"></div></div>\n    <div class=\"buzz-status\" id=\"buzz-status\"></div>\n    <div class=\"clue-actions\" id=\"clue-actions\"></div>\n  </div>\n</div>\n\n<script>\n(function(){\n  const PALETTE = ['#e04f5f','#4fa3e0','#e0b04f','#6fbf7f','#b06fe0','#e0824f','#4fd6c8','#e04fd0'];\n\n  const CATEGORIES = [\n    { name: \"SPQR: Rome's Government\", clues: [\n      {v:100, clue:\"The abbreviation SPQR stands for this Latin phrase meaning 'The Senate and People of Rome.'\", answer:\"Senatus Populusque Romanus\"},\n      {v:200, clue:\"This body of wealthy, appointed elders was the most powerful advisory group in the Roman Republic.\", answer:\"The Senate\"},\n      {v:300, clue:\"Two of these officials, elected annually, jointly held the highest executive power in the Republic.\", answer:\"Consuls\"},\n      {v:400, clue:\"In times of crisis, the Republic could appoint one of these officials to hold near-absolute power for up to six months.\", answer:\"A Dictator\"},\n      {v:500, clue:\"This 5th-century BC law code, displayed publicly on bronze tablets, was Rome's first written body of law.\", answer:\"The Twelve Tables\"},\n    ]},\n    { name: \"Gods & Myths\", clues: [\n      {v:100, clue:\"This king of the Roman gods ruled the sky and hurled thunderbolts.\", answer:\"Jupiter\"},\n      {v:200, clue:\"According to legend, these twin brothers, raised by a she-wolf, founded Rome.\", answer:\"Romulus and Remus\"},\n      {v:300, clue:\"This goddess of love and beauty was claimed as the divine ancestor of Julius Caesar's family.\", answer:\"Venus\"},\n      {v:400, clue:\"This Trojan hero's journey to Italy, told by Virgil in an epic poem, was said to lead to Rome's founding.\", answer:\"Aeneas\"},\n      {v:500, clue:\"This two-faced god of doorways, beginnings, and transitions lends his name to the first month of the year.\", answer:\"Janus\"},\n    ]},\n    { name: \"Emperors & Dynasties\", clues: [\n      {v:100, clue:\"This former general became Rome's first emperor in 27 BC after defeating Mark Antony.\", answer:\"Augustus (Octavian)\"},\n      {v:200, clue:\"Infamous for cruelty and excess, this emperor was rumored to have played music while Rome burned.\", answer:\"Nero\"},\n      {v:300, clue:\"This emperor commissioned a great wall across northern Britain to mark the empire's frontier.\", answer:\"Hadrian\"},\n      {v:400, clue:\"This emperor moved the capital eastward and founded a great city that took his own name.\", answer:\"Constantine the Great\"},\n      {v:500, clue:\"This ruling family, beginning with Augustus, held the throne until Nero's death in 68 AD.\", answer:\"The Julio-Claudian dynasty\"},\n    ]},\n    { name: \"Engineering Marvels\", clues: [\n      {v:100, clue:\"This massive amphitheater in Rome hosted gladiator combats and could seat tens of thousands.\", answer:\"The Colosseum\"},\n      {v:200, clue:\"Romans built these elevated channel structures to carry fresh water across long distances into cities.\", answer:\"Aqueducts\"},\n      {v:300, clue:\"This famous network of durable stone roads gave rise to a saying about all paths leading to one city.\", answer:\"Roman roads\"},\n      {v:400, clue:\"This temple to all the gods, topped with a huge unreinforced dome, still stands largely intact in Rome.\", answer:\"The Pantheon\"},\n      {v:500, clue:\"This ancient building material, a mix of volcanic ash and lime, let Romans build structures that could even harden underwater.\", answer:\"Roman concrete (opus caementicium)\"},\n    ]},\n    { name: \"Latin & Legacy\", clues: [\n      {v:100, clue:\"This short Latin phrase, meaning 'I came, I saw, I conquered,' is credited to Julius Caesar.\", answer:\"Veni, vidi, vici\"},\n      {v:200, clue:\"This Latin phrase, meaning 'seize the day,' urges people to enjoy the present moment.\", answer:\"Carpe diem\"},\n      {v:300, clue:\"This Latin term for a summary of one's education and career literally translates to 'course of life.'\", answer:\"Curriculum vitae\"},\n      {v:400, clue:\"This cautionary Latin phrase, meaning 'let the buyer beware,' comes from Roman commercial law.\", answer:\"Caveat emptor\"},\n      {v:500, clue:\"This Latin motto, meaning 'thus always to tyrants,' was famously shouted by an assassin in a Washington theater in 1865.\", answer:\"Sic semper tyrannis\"},\n    ]},\n  ];\n\n  let myId = localStorage.getItem('spqrPlayerId');\n  if(!myId){ myId = (crypto.randomUUID ? crypto.randomUUID() : 'p-' + Date.now() + '-' + Math.random()); localStorage.setItem('spqrPlayerId', myId); }\n  let myName = '';\n  let myColor = PALETTE[Math.floor(Math.random()*PALETTE.length)];\n  let screen = 'start';\n  let serverOk = true;\n\n  const $ = (id) => document.getElementById(id);\n\n  async function api(path, body, options = {}){\n    const controller = new AbortController();\n    const timeout = setTimeout(() => controller.abort(), options.timeout || 15000);\n    try{\n      const res = await fetch(path, body ? {\n        method: 'POST',\n        headers: {'Content-Type':'application/json'},\n        body: JSON.stringify(body),\n        cache: 'no-store',\n        credentials: 'same-origin',\n        signal: controller.signal,\n        keepalive: !!options.keepalive\n      } : {\n        method: 'GET',\n        cache: 'no-store',\n        credentials: 'same-origin',\n        signal: controller.signal\n      });\n      if(!res.ok) throw new Error('bad status');\n      const data = await res.json();\n      serverOk = true;\n      $('server-warning').classList.add('hidden');\n      return data;\n    }catch(e){\n      if(options.silent) return null;\n      serverOk = false;\n      $('server-warning').classList.remove('hidden');\n      return null;\n    }finally{\n      clearTimeout(timeout);\n    }\n  }\n\n  function escapeHtml(s){\n    return (s||'').replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n  }\n\n  function showScreen(name){\n    screen = name;\n    $('start-screen').classList.toggle('hidden', name !== 'start');\n    $('lobby-screen').classList.toggle('hidden', name !== 'lobby');\n    $('game-screen').classList.toggle('hidden', name !== 'game');\n    if(name !== 'game') $('clue-overlay').classList.add('hidden');\n  }\n\n  async function checkServer(){\n    const res = await api('/api/health', null, {timeout:15000, silent:true});\n    if(!res || !res.ok){\n      $('join-status').textContent = 'Server connection timed out. Try the test again in a few seconds.';\n    }\n  }\n\n  // ---------- Connection test ----------\n  const connectionTestBtn = $('connection-test-btn');\n  if(connectionTestBtn){\n    connectionTestBtn.addEventListener('click', async () => {\n      connectionTestBtn.disabled = true;\n      connectionTestBtn.textContent = 'Testing...';\n      const res = await api('/api/health', null, {timeout:15000, silent:true});\n      $('join-status').textContent = (res && res.ok)\n        ? '✓ Server connection works from this device.'\n        : '✗ The server did not respond within 15 seconds.';\n      connectionTestBtn.disabled = false;\n      connectionTestBtn.textContent = 'Test Server Connection';\n    });\n  }\n\n  // ---------- Pre-join preview ----------\n  function refreshStartScreenPreview(){ return; }\n\n  // ---------- Join ----------\n  $('join-btn').addEventListener('click', joinGame);\n  $('name-input').addEventListener('keydown', (e) => { if(e.key === 'Enter') joinGame(); });\n\n  async function joinGame(){\n    const name = $('name-input').value.trim();\n    if(!name){ $('name-input').focus(); $('join-status').textContent = 'Please enter a name first.'; return; }\n    const btn = $('join-btn');\n    btn.disabled = true;\n    const prevLabel = btn.textContent;\n    btn.textContent = 'Entering...';\n    myName = name.slice(0,18);\n\n    const res = await api('/api/join', {id: myId, name: myName}, {timeout:5000});\n    if(!res || !res.ok){\n      $('join-status').textContent = 'Could not connect to the host. Check the host address and make sure server.py is running.';\n      btn.disabled = false;\n      btn.textContent = prevLabel;\n      return;\n    }\n    if(res.color) myColor = res.color;\n\n    // Fetch state only after the server confirms the join.\n    let state = await api('/api/state?id=' + encodeURIComponent(myId), null, {timeout:5000});\n    if(!state){\n      $('join-status').textContent = 'Joined, but the game server stopped responding. Ask the host to check server.py.';\n      btn.disabled = false;\n      btn.textContent = prevLabel;\n      return;\n    }\n\n    $('join-status').textContent = '';\n    applyGameState(state);\n    showScreen(state.phase === 'playing' ? 'game' : 'lobby');\n    renderScoreboard(state.players || {});\n    if(state.phase === 'lobby') renderLobby(state.players || {});\n    if(state.phase === 'playing'){ renderBoard(state.board); renderClueModal(state.board); }\n\n    btn.disabled = false;\n    btn.textContent = prevLabel;\n    startLoops();\n  }\n\n  // ---------- Lobby ----------\n  $('start-game-btn').addEventListener('click', async () => {\n    const res = await sendSocketAction('/api/start', {});\n    if(res && res.ok) showScreen('game');\n  });\n\n  function renderLobby(players){\n    const list = $('lobby-list');\n    const entries = Object.entries(players);\n    $('lobby-sub').textContent = entries.length <= 1\n      ? 'Waiting for others to gather. Anyone can start once ready.'\n      : entries.length + ' citizens have entered the forum.';\n    if(entries.length === 0){\n      list.innerHTML = '<div class=\"lobby-empty\">No one here yet...</div>';\n      return;\n    }\n    list.innerHTML = entries.map(([id,p]) => `\n      <li><span class=\"dot\" style=\"background:${p.color}\"></span><span>${escapeHtml(p.name)}</span>${id===myId?'<span class=\"you-tag\">YOU</span>':''}</li>\n    `).join('');\n  }\n\n  function renderScoreboard(players){\n    const el = $('scoreboard');\n    const entries = Object.entries(players);\n    if(entries.length === 0){ el.innerHTML = ''; return; }\n    entries.sort((a,b) => b[1].score - a[1].score);\n    el.innerHTML = entries.map(([id,p]) => `\n      <div class=\"chip\"><span class=\"dot\" style=\"background:${p.color}\"></span><span>${escapeHtml(p.name)}</span><span class=\"score\">$${p.score}</span>${id===myId?'<span class=\"you\">(you)</span>':''}</div>\n    `).join('');\n  }\n\n  function renderBoard(board){\n    const el = $('board');\n    let html = '';\n    CATEGORIES.forEach(cat => { html += `<div class=\"cat-cell\">${escapeHtml(cat.name)}</div>`; });\n    for(let vi=0; vi<5; vi++){\n      CATEGORIES.forEach((cat, ci) => {\n        const cell = board.cells[ci+'_'+vi] || {answered:false};\n        const val = cat.clues[vi].v;\n        html += `<div class=\"clue-cell ${cell.answered ? 'used':''}\" data-ci=\"${ci}\" data-vi=\"${vi}\">${cell.answered ? '' : '$'+val}</div>`;\n      });\n    }\n    el.innerHTML = html;\n    el.querySelectorAll('.clue-cell:not(.used)').forEach(node => {\n      node.addEventListener('click', () => openClue(parseInt(node.dataset.ci), parseInt(node.dataset.vi)));\n    });\n  }\n\n  async function openClue(ci, vi){ await sendSocketAction('/api/open_clue', {ci, vi}); }\n  async function buzz(){ await sendSocketAction('/api/buzz', {id: myId, name: myName}); }\n  async function judge(correct){ await sendSocketAction('/api/judge', {correct}); }\n  async function skipClue(){ await sendSocketAction('/api/skip', {}); }\n\n  function closeModal(){ $('clue-overlay').classList.add('hidden'); }\n\n  function renderClueModal(board){\n    const ac = board.activeClue;\n    if(!ac){ closeModal(); return; }\n    const cat = CATEGORIES[ac.ci];\n    const clue = cat.clues[ac.vi];\n    $('clue-overlay').classList.remove('hidden');\n    $('clue-cat').textContent = cat.name;\n    $('clue-value').textContent = '$' + clue.v;\n    $('clue-text').textContent = clue.clue;\n\n    if(ac.revealAnswer){\n      $('answer-block').classList.remove('hidden');\n      $('answer-text').textContent = 'Answer: ' + clue.answer;\n    } else {\n      $('answer-block').classList.add('hidden');\n    }\n\n    const statusEl = $('buzz-status');\n    const actionsEl = $('clue-actions');\n\n    if(ac.buzzedId){\n      statusEl.textContent = (ac.buzzedId===myId ? 'You buzzed in!' : ac.buzzedName + ' buzzed in!') + ' Answer out loud, then judge below.';\n      actionsEl.innerHTML = `<button class=\"btn-correct\" id=\"btn-correct\">✓ Correct</button><button class=\"btn-wrong\" id=\"btn-wrong\">✗ Wrong</button>`;\n      $('btn-correct').onclick = () => judge(true);\n      $('btn-wrong').onclick = () => judge(false);\n    } else if(ac.revealAnswer){\n      statusEl.textContent = 'No one got it — revealing the answer.';\n      actionsEl.innerHTML = '';\n    } else {\n      const lockedOutMe = ac.lockedOut.includes(myId);\n      statusEl.textContent = lockedOutMe ? 'You already answered wrong — waiting for others...' : 'Buzz in when ready!';\n      actionsEl.innerHTML = `<button class=\"btn-gold btn-buzz\" id=\"btn-buzz\" ${lockedOutMe?'disabled':''}>BUZZ</button><button class=\"btn-ghost\" id=\"btn-skip\">Skip / Show Answer</button>`;\n      const buzzBtn = $('btn-buzz');\n      if(buzzBtn) buzzBtn.onclick = buzz;\n      $('btn-skip').onclick = skipClue;\n    }\n  }\n\n  $('reset-btn').addEventListener('click', async () => {\n    if(!confirm(\"Reset the board, everyone's score, and return to the lobby?\")) return;\n    await sendSocketAction('/api/reset', {});\n    closeModal();\n    showScreen('lobby');\n  });\n\n  // ---------- Live multiplayer (single-file HTTP mode) ----------\n  let lastBoardStr = '', lastPlayersStr = '', lastPhase = '';\n  let loopsStarted = false;\n  let pollBusy = false;\n  let pollTimer = null;\n\n  function applyGameState(state){\n    if(!state) return;\n    const playersStr = JSON.stringify(state.players || {});\n    if(playersStr !== lastPlayersStr){\n      lastPlayersStr = playersStr;\n      renderScoreboard(state.players || {});\n      if(screen === 'lobby') renderLobby(state.players || {});\n    }\n    if(state.phase !== lastPhase){\n      lastPhase = state.phase;\n      if(state.phase === 'playing' && screen === 'lobby') showScreen('game');\n      if(state.phase === 'lobby' && screen === 'game') showScreen('lobby');\n    }\n    const boardStr = JSON.stringify(state.board || {});\n    if(boardStr !== lastBoardStr){\n      lastBoardStr = boardStr;\n      if(screen === 'game'){\n        renderBoard(state.board);\n        renderClueModal(state.board);\n      }\n    }\n    renderCursors(state.cursors || {});\n  }\n\n  async function pollGame(){\n    if(screen === 'start' || pollBusy) return;\n    pollBusy = true;\n    try{\n      const state = await api('/api/state?id=' + encodeURIComponent(myId), null, {timeout:2200, silent:true});\n      if(state) applyGameState(state);\n    }finally{\n      pollBusy = false;\n    }\n  }\n\n  async function sendSocketAction(path, data){\n    const result = await api(path, data, {timeout:3500});\n    if(result) await pollGame();\n    return result;\n  }\n\n  function startLoops(){\n    if(loopsStarted) return;\n    loopsStarted = true;\n    pollGame();\n    pollTimer = setInterval(pollGame, 120);\n    document.addEventListener('mousemove', onMouseMove);\n  }\n\n  // ---------- Custom cursor ----------\n  function ensureMyCursor(){\n    if($('my-cursor')) return $('my-cursor');\n    const node = document.createElement('div');\n    node.id = 'my-cursor';\n    node.className = 'cursor';\n    node.style.opacity = '0';\n    node.innerHTML = `<svg width=\"24\" height=\"24\" viewBox=\"0 0 22 22\"><path d=\"M2 1 L2 19 L7 15 L10 21 L13 19.5 L10 13.5 L17 13 Z\" fill=\"var(--gold)\" stroke=\"#2a1c04\" stroke-width=\"1.4\"/></svg>`;\n    $('cursor-layer').appendChild(node);\n    return node;\n  }\n  function onLocalCursorMove(e){\n    const node = ensureMyCursor();\n    node.style.opacity = '1';\n    node.style.transform = `translate(${e.clientX}px, ${e.clientY}px)`;\n  }\n  document.addEventListener('DOMContentLoaded', () => {\n    ensureMyCursor();\n    document.addEventListener('mousemove', onLocalCursorMove);\n    document.addEventListener('mouseleave', () => { const n=$('my-cursor'); if(n) n.style.opacity='0'; });\n    // Do not poll the server before joining. This keeps the start page lightweight and avoids repeated cold-start requests.\n    checkServer();\n  });\n\n  let lastCursorSend = 0;\n  let cursorSendPending = false;\n  let queuedCursorEvent = null;\n\n  function sendCursor(e){\n    queuedCursorEvent = e;\n    if(cursorSendPending) return;\n    cursorSendPending = true;\n    const now = performance.now();\n    const wait = Math.max(0, 50 - (now - lastCursorSend));\n    setTimeout(async () => {\n      const ev = queuedCursorEvent;\n      queuedCursorEvent = null;\n      cursorSendPending = false;\n      if(!ev) return;\n      lastCursorSend = performance.now();\n      await api('/api/cursor', {id:myId, x:ev.clientX/window.innerWidth, y:ev.clientY/window.innerHeight}, {timeout:1500, silent:true});\n    }, wait);\n  }\n\n  function onMouseMove(e){\n    const node = ensureMyCursor();\n    node.style.opacity = '1';\n    node.style.transform = `translate3d(${e.clientX}px, ${e.clientY}px, 0)`;\n    sendCursor(e);\n  }\n\n  const remoteCursors = new Map();\n\n  function renderCursors(cursors){\n    const layer = $('cursor-layer');\n    const activeIds = new Set();\n\n    Object.entries(cursors).forEach(([id, data]) => {\n      if(id === myId) return;\n      activeIds.add(id);\n\n      let node = document.getElementById('cur-' + id);\n      if(!node){\n        node = document.createElement('div');\n        node.className = 'cursor';\n        node.id = 'cur-' + id;\n        node.innerHTML = `<svg width=\"22\" height=\"22\" viewBox=\"0 0 22 22\"><path d=\"M2 1 L2 19 L7 15 L10 21 L13 19.5 L10 13.5 L17 13 Z\" fill=\"${data.color}\" stroke=\"#000\" stroke-width=\"1\"/></svg><div class=\"label\" style=\"border-color:${data.color}66\">${escapeHtml(data.name)}</div>`;\n        layer.appendChild(node);\n      }\n\n      let target = remoteCursors.get(id);\n      if(!target){\n        target = {\n          x: data.x * window.innerWidth,\n          y: data.y * window.innerHeight,\n          tx: data.x * window.innerWidth,\n          ty: data.y * window.innerHeight\n        };\n        remoteCursors.set(id, target);\n      }else{\n        target.tx = data.x * window.innerWidth;\n        target.ty = data.y * window.innerHeight;\n      }\n    });\n\n    Array.from(remoteCursors.keys()).forEach(id => {\n      if(!activeIds.has(id)){\n        remoteCursors.delete(id);\n        const node = document.getElementById('cur-' + id);\n        if(node) node.remove();\n      }\n    });\n  }\n\n  function animateRemoteCursors(){\n    remoteCursors.forEach((target, id) => {\n      const node = document.getElementById('cur-' + id);\n      if(!node) return;\n      target.x += (target.tx - target.x) * 0.42;\n      target.y += (target.ty - target.y) * 0.42;\n      node.style.transform = `translate3d(${target.x}px, ${target.y}px, 0)`;\n    });\n    requestAnimationFrame(animateRemoteCursors);\n  }\n  requestAnimationFrame(animateRemoteCursors);\n\n})();\n</script>\n</body>\n</html>"

def default_board():
    return {"cells": {f"{ci}_{vi}": {"answered": False} for ci in range(5) for vi in range(5)}, "activeClue": None}

STATE = {"board": default_board(), "players": {}, "phase": "lobby", "cursors": {}}

def cleanup_stale(now=None):
    now = now or time.time()
    with LOCK:
        stale = [pid for pid,p in STATE["players"].items() if now-p.get("lastSeen",0)>PLAYER_TTL]
        for pid in stale:
            STATE["players"].pop(pid,None); STATE["cursors"].pop(pid,None)
        stale_c = [pid for pid,c in STATE["cursors"].items() if pid not in STATE["players"] or now-c.get("ts",0)>CURSOR_TTL]
        for pid in stale_c: STATE["cursors"].pop(pid,None)

def snapshot(pid=None):
    with LOCK:
        now=time.time()
        if pid in STATE["players"]: STATE["players"][pid]["lastSeen"]=now
        cleanup_stale(now)
        players={k:{"name":v["name"],"score":v["score"],"color":v["color"]} for k,v in STATE["players"].items()}
        cursors={k:dict(v) for k,v in STATE["cursors"].items()}
        board=json.loads(json.dumps(STATE["board"]))
        return {"board":board,"players":players,"phase":STATE["phase"],"cursors":cursors}

class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "SPQRJeopardy/1.0"
    def log_message(self, fmt, *args): pass
    def send_bytes(self, body, status=200, ctype="text/plain; charset=utf-8"):
        self.send_response(status)
        self.send_header("Content-Type",ctype)
        self.send_header("Content-Length",str(len(body)))
        self.send_header("Cache-Control","no-store, no-cache, must-revalidate")
        self.send_header("Pragma","no-cache")
        self.send_header("Connection","close")
        self.send_header("Access-Control-Allow-Origin","*")
        self.send_header("Access-Control-Allow-Methods","GET,POST,OPTIONS")
        self.send_header("Access-Control-Allow-Headers","Content-Type")
        self.end_headers()
        try: self.wfile.write(body); self.wfile.flush()
        except BrokenPipeError: pass
    def send_json(self,obj,status=200):
        self.send_bytes(json.dumps(obj,separators=(",",":"),ensure_ascii=False).encode(),status,"application/json; charset=utf-8")
    def read_json(self):
        try:
            n=int(self.headers.get("Content-Length","0")); raw=self.rfile.read(n) if n else b""
            return json.loads(raw.decode("utf-8")) if raw else {}
        except Exception: return {}
    def do_OPTIONS(self):
        self.send_response(204); self.send_header("Access-Control-Allow-Origin","*"); self.send_header("Access-Control-Allow-Methods","GET,POST,OPTIONS"); self.send_header("Access-Control-Allow-Headers","Content-Type"); self.send_header("Content-Length","0"); self.send_header("Connection","close"); self.end_headers()
    def do_GET(self):
        path=urlparse(self.path).path
        if path=="/api/health": self.send_json({"ok":True}); return
        if path=="/api/state":
            q=parse_qs(urlparse(self.path).query); pid=(q.get("id") or [None])[0]; self.send_json(snapshot(pid)); return
        if path in ("/","/index.html"):
            self.send_bytes(INDEX_HTML.encode("utf-8"),200,"text/html; charset=utf-8"); return
        self.send_json({"error":"not found"},404)
    def do_POST(self):
        path=urlparse(self.path).path; data=self.read_json()
        with LOCK:
            now=time.time()
            if path=="/api/join":
                pid=str(data.get("id") or "").strip(); name=str(data.get("name") or "Citizen").strip()[:18] or "Citizen"
                if not pid: self.send_json({"ok":False,"error":"missing id"},400); return
                existing=STATE["players"].get(pid)
                used={p["color"] for p in STATE["players"].values()}
                color=existing["color"] if existing else next((c for c in PALETTE if c not in used),PALETTE[len(STATE["players"])%len(PALETTE)])
                STATE["players"][pid]={"name":name,"score":existing["score"] if existing else 0,"color":color,"lastSeen":now}
                self.send_json({"ok":True,"color":color}); return
            if path=="/api/cursor":
                pid=str(data.get("id") or "")
                if pid in STATE["players"]:
                    try: x=max(0.0,min(1.0,float(data.get("x",0)))); y=max(0.0,min(1.0,float(data.get("y",0))))
                    except Exception: x=y=0.0
                    p=STATE["players"][pid]; p["lastSeen"]=now; STATE["cursors"][pid]={"name":p["name"],"color":p["color"],"x":x,"y":y,"ts":now}
                self.send_json({"ok":True}); return
            if path=="/api/leave":
                pid=str(data.get("id") or ""); STATE["players"].pop(pid,None); STATE["cursors"].pop(pid,None); self.send_json({"ok":True}); return
            if path=="/api/start":
                cleanup_stale(now)
                if not STATE["players"]: self.send_json({"ok":False,"error":"no players"},400); return
                STATE["phase"]="playing"; self.send_json({"ok":True}); return
            if path=="/api/reset":
                STATE["board"]=default_board(); STATE["phase"]="lobby"; STATE["cursors"]={}
                for p in STATE["players"].values(): p["score"]=0
                self.send_json({"ok":True}); return
            if path=="/api/open_clue":
                try: ci=int(data.get("ci")); vi=int(data.get("vi"))
                except Exception: self.send_json({"ok":False,"error":"invalid clue"},400); return
                key=f"{ci}_{vi}"; cell=STATE["board"]["cells"].get(key)
                if STATE["phase"]=="playing" and 0<=ci<5 and 0<=vi<5 and cell and not cell["answered"] and STATE["board"]["activeClue"] is None:
                    STATE["board"]["activeClue"]={"ci":ci,"vi":vi,"buzzedId":None,"buzzedName":None,"lockedOut":[],"revealAnswer":False}
                self.send_json({"ok":True}); return
            if path=="/api/buzz":
                pid=str(data.get("id") or ""); ac=STATE["board"]["activeClue"]
                if ac and pid in STATE["players"] and not ac["buzzedId"] and pid not in ac["lockedOut"]:
                    STATE["players"][pid]["lastSeen"]=now; ac["buzzedId"]=pid; ac["buzzedName"]=STATE["players"][pid]["name"]
                self.send_json({"ok":True}); return
            if path=="/api/judge":
                ac=STATE["board"]["activeClue"]; correct=bool(data.get("correct"))
                if ac and ac["buzzedId"] in STATE["players"]:
                    pid=ac["buzzedId"]; value=(ac["vi"]+1)*100; STATE["players"][pid]["score"] += value if correct else -value
                    if correct:
                        STATE["board"]["cells"][f'{ac["ci"]}_{ac["vi"]}']={"answered":True}; STATE["board"]["activeClue"]=None
                    else:
                        ac["lockedOut"].append(pid); ac["buzzedId"]=None; ac["buzzedName"]=None
                        if len(ac["lockedOut"])>=max(len(STATE["players"]),1):
                            ac["revealAnswer"]=True; STATE["board"]["cells"][f'{ac["ci"]}_{ac["vi"]}']={"answered":True}
                            clue_ref=ac
                            threading.Thread(target=clear_later,args=(clue_ref,),daemon=True).start()
                self.send_json({"ok":True}); return
            if path=="/api/skip":
                ac=STATE["board"]["activeClue"]
                if ac:
                    STATE["board"]["cells"][f'{ac["ci"]}_{ac["vi"]}']={"answered":True}; ac["revealAnswer"]=True; clue_ref=ac
                    threading.Thread(target=clear_later,args=(clue_ref,),daemon=True).start()
                self.send_json({"ok":True}); return
        self.send_json({"error":"not found"},404)

def clear_later(clue_ref):
    time.sleep(REVEAL_DURATION)
    with LOCK:
        if STATE["board"]["activeClue"] is clue_ref: STATE["board"]["activeClue"]=None

def main():
    httpd=ThreadingHTTPServer((HOST,PORT),Handler)
    print("SPQR JEOPARDY is running on port",PORT,flush=True)
    httpd.serve_forever()

if __name__=="__main__": main()
